file.content:
  {
	"$schema": "https://schemas.wp.org/trunk/block.json",
	"apiVersion": 3,
	"name": "telex/block-post-navigation",
	"version": "0.1.0",
	"title": "Post Navigation",
	"category": "widgets",
	"icon": "leftright",
	"description": "Display previous and next post navigation links with featured images and overlaid titles.",
	"example": {
		"attributes": {
			"textColor": "#ffffff",
			"overlayOpacity": 0.7,
			"cardHeight": 200
		}
	},
	"attributes": {
		"textColor": {
			"type": "string",
			"default": "#ffffff"
		},
		"overlayOpacity": {
			"type": "number",
			"default": 0.7
		},
		"cardHeight": {
			"type": "number",
			"default": 200
		}
	},
	"supports": {
		"html": false,
		"align": ["wide", "full"],
		"spacing": {
			"margin": true,
			"padding": true
		}
	},
	"textdomain": "post-navigation-block-wp",
	"editorScript": "file:./index.js",
	"editorStyle": "file:./index.css",
	"style": "file:./style-index.css",
	"viewScript": "file:./view.js",
	"render": "file:./render.php"
}

  /**
 * Registers a new block provided a unique name and an object defining its behavior.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
import { registerBlockType } from '@wordpress/blocks';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * All files containing `style` keyword are bundled together. The code used
 * gets applied both to the front of your site and to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './style.scss';

/**
 * Internal dependencies
 */
import Edit from './edit';
import metadata from './block.json';

/**
 * Every block starts by registering a new block type definition.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
registerBlockType( metadata.name, {
	/**
	 * @see ./edit.js
	 */
	edit: Edit,
} );

  /**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from '@wordpress/i18n';

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { 
	useBlockProps, 
	InspectorControls, 
	PanelColorSettings 
} from '@wordpress/block-editor';

/**
 * WordPress components
 */
import { 
	PanelBody, 
	RangeControl, 
	Notice 
} from '@wordpress/components';

/**
 * React hooks
 */
import { useState, useEffect } from '@wordpress/element';

/**
 * WordPress data
 */
import { useSelect } from '@wordpress/data';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './editor.scss';

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#edit
 *
 * @return {Element} Element to render.
 */
export default function Edit({ attributes, setAttributes, context }) {
	const { textColor, overlayOpacity, cardHeight } = attributes;

	const [isInPostEditor, setIsInPostEditor] = useState(false);

	// Check if we're in a post editor context
	const { postType, postId } = useSelect((select) => {
		const { getCurrentPostType, getCurrentPostId } = select('core/editor') || {};
		return {
			postType: getCurrentPostType ? getCurrentPostType() : null,
			postId: getCurrentPostId ? getCurrentPostId() : null,
		};
	}, []);

	useEffect(() => {
		setIsInPostEditor(postType === 'post' && postId);
	}, [postType, postId]);

	const blockProps = useBlockProps({
		style: {
			'--text-color': textColor,
			'--overlay-opacity': overlayOpacity,
			'--card-height': `${cardHeight}px`,
		},
	});

	// Mock data for preview
	const mockPrevious = {
		title: __('Previous Post Title', 'post-navigation-block-wp'),
		image: 'https://via.placeholder.com/400x200/4a90e2/ffffff?text=Previous+Post',
		url: '#'
	};

	const mockNext = {
		title: __('Next Post Title', 'post-navigation-block-wp'),
		image: 'https://via.placeholder.com/400x200/7b68ee/ffffff?text=Next+Post',
		url: '#'
	};

	return (
		<>
			<InspectorControls>
				<PanelBody title={__('Appearance Settings', 'post-navigation-block-wp')}>
					<PanelColorSettings
						title={__('Colors', 'post-navigation-block-wp')}
						colorSettings={[
							{
								value: textColor,
								onChange: (color) => setAttributes({ textColor: color || '#ffffff' }),
								label: __('Text Color', 'post-navigation-block-wp'),
							},
						]}
					/>
					<RangeControl
						label={__('Overlay Opacity', 'post-navigation-block-wp')}
						value={overlayOpacity}
						onChange={(value) => setAttributes({ overlayOpacity: value })}
						min={0}
						max={1}
						step={0.1}
					/>
					<RangeControl
						label={__('Card Height (px)', 'post-navigation-block-wp')}
						value={cardHeight}
						onChange={(value) => setAttributes({ cardHeight: value })}
						min={150}
						max={400}
						step={10}
					/>
				</PanelBody>
			</InspectorControls>

			<div {...blockProps}>
				{!isInPostEditor && (
					<Notice status="info" isDismissible={false}>
						{__('This block will display post navigation when added to a post. Preview shown below with placeholder content.', 'post-navigation-block-wp')}
					</Notice>
				)}

				<div className="wp-block-telex-post-navigation__container">
					<div className="wp-block-telex-post-navigation__grid">
						<div className="wp-block-telex-post-navigation__card wp-block-telex-post-navigation__previous">
							<div 
								className="wp-block-telex-post-navigation__card-bg"
								style={{ backgroundImage: `url(${mockPrevious.image})` }}
							>
								<div className="wp-block-telex-post-navigation__overlay">
									<div className="wp-block-telex-post-navigation__content">
										<span className="wp-block-telex-post-navigation__label">
											{__('← Previous', 'post-navigation-block-wp')}
										</span>
										<h3 className="wp-block-telex-post-navigation__title">
											{mockPrevious.title}
										</h3>
									</div>
								</div>
							</div>
						</div>

						<div className="wp-block-telex-post-navigation__card wp-block-telex-post-navigation__next">
							<div 
								className="wp-block-telex-post-navigation__card-bg"
								style={{ backgroundImage: `url(${mockNext.image})` }}
							>
								<div className="wp-block-telex-post-navigation__overlay">
									<div className="wp-block-telex-post-navigation__content">
										<span className="wp-block-telex-post-navigation__label">
											{__('Next →', 'post-navigation-block-wp')}
										</span>
										<h3 className="wp-block-telex-post-navigation__title">
											{mockNext.title}
										</h3>
									</div>
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>
		</>
	);
}

  /**
 * The following styles get applied both on the front of your site
 * and in the editor.
 *
 * Replace them with your own styles or remove the file completely.
 */

.wp-block-telex-post-navigation {
	--text-color: #ffffff;
	--overlay-opacity: 0.7;
	--card-height: 200px;

	margin: 2rem 0;
}

.wp-block-telex-post-navigation__container {
	max-width: 100%;
	margin: 0 auto;
}

.wp-block-telex-post-navigation__grid {
	display: grid;
	grid-template-columns: 1fr 1fr;
	gap: 1rem;

	@media (max-width: 768px) {
		grid-template-columns: 1fr;
		gap: 1rem;
	}
}

.wp-block-telex-post-navigation__grid--single {
	display: flex;
	justify-content: center;

	.wp-block-telex-post-navigation__card {
		max-width: 500px;
		width: 100%;
	}
}

.wp-block-telex-post-navigation__card {
	position: relative;
	height: var(--card-height);
	border-radius: 8px;
	overflow: hidden;
	transition: transform 0.3s ease, box-shadow 0.3s ease;
	cursor: pointer;

	&:hover {
		transform: translateY(-4px);
		box-shadow: 0 8px 25px rgba(0, 0, 0, 0.15);

		.wp-block-telex-post-navigation__card-bg {
			transform: scale(1.05);
		}
	}
}

.wp-block-telex-post-navigation__card-bg {
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
	background-size: cover;
	background-position: center;
	background-repeat: no-repeat;
	transition: transform 0.3s ease;

	&:not([style*="background-image"]) {
		background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
	}
}

.wp-block-telex-post-navigation__overlay {
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
	background: rgba(0, 0, 0, var(--overlay-opacity));
	display: flex;
	align-items: flex-end;
	padding: 1.5rem;
}

.wp-block-telex-post-navigation__content {
	color: var(--text-color);
}

.wp-block-telex-post-navigation__label {
	display: block;
	font-size: 0.875rem;
	opacity: 0.9;
	margin-bottom: 0.25rem;
	font-weight: 500;
	text-transform: uppercase;
	letter-spacing: 0.5px;
}

.wp-block-telex-post-navigation__title {
	margin: 0;
	font-size: 1.25rem;
	font-weight: 700;
	line-height: 1.3;
	color: inherit;

	@media (max-width: 768px) {
		font-size: 1.125rem;
	}
}

.wp-block-telex-post-navigation__card a {
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
	text-decoration: none;
	color: inherit;
	z-index: 10;
}

/* Fallback styles when no featured image */
.wp-block-telex-post-navigation__card--no-image {
	.wp-block-telex-post-navigation__card-bg {
		background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
	}

	&.wp-block-telex-post-navigation__previous {
		.wp-block-telex-post-navigation__card-bg {
			background: linear-gradient(135deg, #4a90e2 0%, #357abd 100%);
		}
	}

	&.wp-block-telex-post-navigation__next {
		.wp-block-telex-post-navigation__card-bg {
			background: linear-gradient(135deg, #7b68ee 0%, #6a5acd 100%);
		}
	}
}

/* Accessibility improvements */
.wp-block-telex-post-navigation__card:focus-within {
	outline: 2px solid #005cee;
	outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
	.wp-block-telex-post-navigation__card {
		transition: none;

		&:hover {
			transform: none;
		}
	}

	.wp-block-telex-post-navigation__card-bg {
		transition: none;

		.wp-block-telex-post-navigation__card:hover & {
			transform: none;
		}
	}
}

  /**
 * The following styles get applied inside the editor only.
 *
 * Replace them with your own styles or remove the file completely.
 */

.wp-block-telex-post-navigation {
	.components-notice {
		margin-bottom: 1rem;
	}
}

/* Editor-specific hover effects */
.block-editor-block-list__block .wp-block-telex-post-navigation__card:hover {
	.wp-block-telex-post-navigation__card-bg {
		transform: scale(1.02);
	}
}

/* Editor selection states */
.wp-block-telex-post-navigation.is-selected {
	.wp-block-telex-post-navigation__card {
		outline: 1px solid var(--wp-admin-theme-color, #007cba);
		outline-offset: 1px;
	}
}

  /**
 * Use this file for JavaScript code that you want to run in the front-end
 * on posts/pages that contain this block.
 *
 * When this file is defined as the value of the `viewScript` property
 * in `block.json` it will be enqueued on the front end of the site.
 *
 * Example:
 *
 * ```js
 * {
 *   "viewScript": "file:./view.js"
 * }
 * ```
 *
 * If you're not making any changes to this file because your project doesn't need any
 * JavaScript running in the front-end, then you should delete this file and remove
 * the `viewScript` property from `block.json`.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-metadata/#view-script
 */

document.addEventListener('DOMContentLoaded', function() {
	// Add keyboard navigation support
	const navigationCards = document.querySelectorAll('.wp-block-telex-post-navigation__card a');

	navigationCards.forEach(card => {
		// Handle keyboard navigation
		card.addEventListener('keydown', function(e) {
			if (e.key === 'Enter' || e.key === ' ') {
				e.preventDefault();
				this.click();
			}
		});

		// Add ARIA labels for better accessibility
		const cardElement = card.closest('.wp-block-telex-post-navigation__card');
		const titleElement = cardElement.querySelector('.wp-block-telex-post-navigation__title');
		const labelElement = cardElement.querySelector('.wp-block-telex-post-navigation__label');

		if (titleElement && labelElement) {
			card.setAttribute('aria-label', labelElement.textContent + ': ' + titleElement.textContent);
		}
	});

	// Preload images on hover for better performance
	const cardBackgrounds = document.querySelectorAll('.wp-block-telex-post-navigation__card-bg');
	cardBackgrounds.forEach(bg => {
		const card = bg.closest('.wp-block-telex-post-navigation__card');
		card.addEventListener('mouseenter', function() {
			const bgImage = window.getComputedStyle(bg).backgroundImage;
			if (bgImage && bgImage !== 'none') {
				// Image is already loaded as background
				return;
			}
		});
	});
});
